CREATE OR REPLACE PROCEDURE sp (
    arg1 VARCHAR2,
    arg2 NUMBER,
    arg3 VARCHAR2,
    arg4 VARCHAR2
)
AS
    v_mismatch_count NUMBER;
    v_budget_avg     NUMBER;
    v_enroll_avg     NUMBER;
    v_budget_count   NUMBER := 0;
    v_school_count   NUMBER := 0;
    v_total_count    NUMBER := 0;
BEGIN
    SAVEPOINT sp_savepoint;

    SELECT AVG("Budgeted") INTO v_budget_avg FROM budget;

    SELECT AVG("Enrollment") INTO v_enroll_avg FROM "School";

    IF v_budget_avg < v_enroll_avg THEN
        NULL;
    END IF;

    SELECT COUNT(*) INTO v_mismatch_count
      FROM "School"
     WHERE "Mascot" = arg3;

    IF v_mismatch_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20002, 'No School record matches the mascot; budget updates skipped');
    END IF;

    SELECT COUNT(*) INTO v_budget_count
      FROM budget
     WHERE "Budget_invested_percent" = arg1;

    UPDATE budget
       SET "total_budget_percent_budgeted" = arg2
     WHERE "Budget_invested_percent" = arg1;

    SELECT COUNT(*) INTO v_school_count
      FROM "School"
     WHERE "Mascot" = arg3;

    UPDATE "School"
       SET "Location" = arg4
     WHERE "Mascot" = arg3;

    v_total_count := v_budget_count + v_school_count;

    IF v_total_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'No matching records were updated');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO sp_savepoint;
        RAISE;
END;
/

